from pydantic import BaseModel, Field, field_validator, model_validator, EmailStr, ConfigDict
from typing import Optional
from datetime import datetime

# Separate schemas for create/update/response
class UserBase(BaseModel):
    username: str = Field(min_length=3, max_length=50, pattern=r'^[a-zA-Z0-9_]+$')
    email: EmailStr

class UserCreate(UserBase):
    password: str = Field(min_length=8)
    confirm_password: str

    @model_validator(mode='after')
    def passwords_match(self):
        if self.password != self.confirm_password:
            raise ValueError('Passwords do not match')
        return self

class UserUpdate(BaseModel):
    username: Optional[str] = Field(None, min_length=3)
    email: Optional[EmailStr] = None
    # all fields optional for PATCH semantics

class UserResponse(UserBase):
    id: int
    created_at: datetime
    # no password field — never expose it

    model_config = ConfigDict(from_attributes=True)  # read from SQLAlchemy objects

# Field validators
class OrderCreate(BaseModel):
    items: list[str] = Field(min_length=1)
    total_price: float = Field(gt=0)
    currency: str = Field(default='USD')

    @field_validator('currency')
    @classmethod
    def currency_must_be_valid(cls, v: str) -> str:
        valid = {'USD', 'EUR', 'GBP', 'JPY'}
        if v.upper() not in valid:
            raise ValueError(f'Currency must be one of {valid}')
        return v.upper()

# Usage in FastAPI
@app.post('/users/', response_model=UserResponse)
async def create_user(user: UserCreate):
    # user.username, user.email, user.password are validated and typed
